import AppKit

/// Records everything the user copies (text, and file paths when files are
/// copied) into `HistoryStore.clipboard`. macOS has no "clipboard changed"
/// notification: every clipboard manager polls `changeCount`, and so do we,
/// twice a second (it's a single integer read).
///
/// Skipped, per the nspasteboard.org conventions:
/// - ConcealedType: passwords from 1Password, Bitwarden, Keychain Access…
/// - TransientType: temporary content, including Yell Flow's own paste (that
///   text is already in the dictation history) and the clipboard it restores.
/// - AutoGeneratedType: content an app put there without the user copying.
enum ClipboardHistory {

    private static let skipped: Set<NSPasteboard.PasteboardType> = [
        .init("org.nspasteboard.ConcealedType"),
        .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType")
    ]
    /// A single copy larger than this is kept truncated, so one huge log can't
    /// bloat the history file.
    private static let maxCharacters = 2_000_000

    private static var lastChangeCount = NSPasteboard.general.changeCount
    private static var timer: Timer?

    /// Must be called on the main thread.
    static func start() {
        guard timer == nil else { return }
        lastChangeCount = NSPasteboard.general.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { _ in check() }
        Log.write("clipboard history on — \(HistoryStore.clipboard.path)")
    }

    private static func check() {
        let pasteboard = NSPasteboard.general
        let current = pasteboard.changeCount
        guard current != lastChangeCount else { return }
        lastChangeCount = current

        let types = Set(pasteboard.types ?? [])
        guard types.isDisjoint(with: skipped) else { return }

        var text = pasteboard.string(forType: .string)
        if text == nil || text?.isEmpty == true,
           let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            text = urls.map(\.path).joined(separator: "\n")
        }
        guard var copied = text, !copied.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        if copied.count > maxCharacters {
            copied = String(copied.prefix(maxCharacters)) + "\n[…]"
        }
        HistoryStore.clipboard.addMovingToTop(copied)
    }
}
